feed:
	{{ config.title }}
	{{ config.description }}
	
  	
	Zola
	{%- if last_updated is defined %}
	{{ last_updated | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
	{%- endif %}
	
        {{ config.extra.author | escape_xml | safe }}
        {{ config.base_url | safe }}
    
	{{ config.base_url ~ "favicon/android-chrome-192x192.png" | safe }}
	{{ feed_url | safe }}
	{%- for page in pages %}
	{%- set hide_from_home = page.extra.hide_from_home | default(value=false) %}
	{%- if not hide_from_home %}

		{{ page.title }}
		{{ page.date | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
		{{ (page.updated or page.date) | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
		
		{{ page.permalink | safe }}
		{{ page.description }}
		{%- for tag in page.taxonomies.tags %}
		
		{%- endfor %}

	{%- endif %}
	{%- endfor %}
